import * as THREE from 'three';
import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

export function mazeMesh(grid, opts={}) {
  const { cell=2, wallHeight=1.5, thickness=0.2 } = opts;
  const rows = grid.length, cols = grid[0].length;
  const geos=[];
  const ox = -(cols*cell)/2, oz = -(rows*cell)/2;
  const addWall = (x,z,len,alongX) => {
    const g = new THREE.BoxGeometry(alongX ? len : thickness, wallHeight, alongX ? thickness : len);
    g.translate(x, wallHeight/2, z);
    geos.push(g);
  };
  for (let y=0;y<rows;y++) for (let x=0;x<cols;x++) {
    const c = grid[y][x];
    const cx = ox + (x+0.5)*cell, cz = oz+(y+0.5)*cell;
    if (c.n) addWall(cx, cz - cell/2, cell+thickness, true);
    if (c.w) addWall(cx - cell/2, cz, cell+thickness, false);
    if (y===rows-1 && c.s) addWall(cx, cz+cell/2, cell+thickness, true);
    if (x===cols-1 && c.e) addWall(cx+cell/2, cz, cell+thickness, false);
  }
  const merged = mergeGeometries(geos);
  return merged;
}
