import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';

/**
 * Deterministic seeded RNG (mulberry32).
 */
export function mulberry32(seed) {
  let a = seed >>> 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

/**
 * Generate a perfect maze using iterative recursive-backtracker DFS.
 *
 * Returns a grid (array of rows) where each cell is
 *   { n, s, e, w }  // true = wall present on that side
 * grid[y][x], y in [0, rows), x in [0, cols).
 */
export function generateMaze(cols, rows, seed) {
  if (cols < 1 || rows < 1) throw new Error('maze dimensions must be >= 1');
  const rand = mulberry32(seed);

  const cells = [];
  for (let y = 0; y < rows; y++) {
    const row = [];
    for (let x = 0; x < cols; x++) row.push({ n: true, s: true, e: true, w: true });
    cells.push(row);
  }

  const visited = Array.from({ length: rows }, () => new Array(cols).fill(false));

  // dir -> [dx, dy, own wall, opposite wall]
  const DIRS = [
    [0, -1, 'n', 's'],
    [0, 1, 's', 'n'],
    [1, 0, 'e', 'w'],
    [-1, 0, 'w', 'e'],
  ];

  const stack = [[0, 0]];
  visited[0][0] = true;

  while (stack.length > 0) {
    const [x, y] = stack[stack.length - 1];

    // Collect unvisited neighbors in randomized order.
    const candidates = [];
    for (let i = 0; i < 4; i++) {
      const r = Math.floor(rand() * 4) % 4;
      if (!candidates.includes(r)) candidates.push(r);
    }

    let carved = false;
    for (const ci of candidates) {
      const [dx, dy, wall, opp] = DIRS[ci];
      const nx = x + dx;
      const ny = y + dy;
      if (nx < 0 || nx >= cols || ny < 0 || ny >= rows || visited[ny][nx]) continue;

      // Remove walls on both sides => one passage carved.
      cells[y][x][wall] = false;
      cells[ny][nx][opp] = false;

      visited[ny][nx] = true;
      stack.push([nx, ny]);
      carved = true;
      break;
    }

    if (!carved) stack.pop(); // backtrack
  }

  return cells;
}

/**
 * Breadth-first search shortest path through open passages.
 *
 * @param {Array<Array<{n:boolean,s:boolean,e:boolean,w:boolean}>>} grid
 * @param {[number, number]} start  [col, row]
 * @param {[number, number]} goal   [col, row]
 * @returns {Array<[number, number]>} path of [col, row] from start to goal
 */
export function solveMaze(grid, start, goal) {
  const rows = grid.length;
  const cols = grid[0].length;
  const [sx, sy] = start;
  const [gx, gy] = goal;

  const prev = new Map();
  const key = (x, y) => y * cols + x;
  const seen = new Set([key(sx, sy)]);
  const queue = [[sx, sy]];

  const STEPS = [
    [0, -1, 'n'],
    [0, 1, 's'],
    [1, 0, 'e'],
    [-1, 0, 'w'],
  ];

  while (queue.length > 0) {
    const [x, y] = queue.shift();
    if (x === gx && y === gy) {
      const path = [];
      let k = key(x, y);
      let cur = [x, y];
      while (true) {
        path.push(cur);
        const p = prev.get(k);
        if (!p) break;
        cur = p;
        k = key(p[0], p[1]);
      }
      return path.reverse();
    }
    for (const [dx, dy, wall] of STEPS) {
      const nx = x + dx;
      const ny = y + dy;
      if (grid[y][x][wall]) continue; // wall blocks passage
      if (nx < 0 || nx >= cols || ny < 0 || ny >= rows) continue;
      const k = key(nx, ny);
      if (seen.has(k)) continue;
      seen.add(k);
      prev.set(k, [x, y]);
      queue.push([nx, ny]);
    }
  }

  throw new Error('no path found');
}

/**
 * Build a merged BufferGeometry of wall boxes for the maze.
 *
 * Only the n/w sides are emitted per cell (plus s on last row and
 * e on last column) so shared walls are not duplicated.
 *
 * @returns {THREE.BufferGeometry} single merged geometry, centered on origin
 */
export function mazeMesh(grid, { cell = 2, wallHeight = 1.5, thickness = 0.2 } = {}) {
  const rows = grid.length;
  const cols = grid[0].length;

  const geometries = [];
  const ox = -(cols * cell) / 2;
  const oz = -(rows * cell) / 2;

  const addWall = (cx, cz, lengthAlongX) => {
    const g = new THREE.BoxGeometry(
      lengthAlongX ? cell + thickness : thickness,
      wallHeight,
      lengthAlongX ? thickness : cell + thickness,
    );
    g.translate(cx, wallHeight / 2, cz);
    geometries.push(g);
  };

  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      const c = grid[y][x];
      const cx = ox + (x + 0.5) * cell;
      const cz = oz + (y + 0.5) * cell;
      if (c.n) addWall(cx, cz - cell / 2, true);
      if (c.w) addWall(cx - cell / 2, cz, false);
      if (y === rows - 1 && c.s) addWall(cx, cz + cell / 2, true);
      if (x === cols - 1 && c.e) addWall(cx + cell / 2, cz, false);
    }
  }

  return mergeGeometries(geometries);
}
